# Import necessary modules
from rest_framework.response import Response
from rest_framework.decorators import api_view
from rest_framework.views import APIView
from rest_framework.authentication import TokenAuthentication
from rest_framework.permissions import IsAuthenticated
from .models import User
from .serializers import UserSerializer

# Define the RegisterView class
class RegisterView(APIView):
    authentication_classes = [TokenAuthentication]
    permission_classes = [IsAuthenticated]

    def post(self, request):
        serializer = UserSerializer(data=request.data)
        if serializer.is_valid():
            user = serializer.save()
            data = {'message': 'User created successfully', 'user': UserSerializer(user).data}
            # Include the refresh token in the response
            data['refresh_token'] = user.refresh_token
            return Response(data, status=status.HTTP_201_CREATED)
        else:
            return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

# Define the LoginView class
class LoginView(APIView):
    authentication_classes = [TokenAuthentication]
    permission_classes = [IsAuthenticated]

    def post(self, request):
        serializer = UserSerializer(data=request.data)
        if serializer.is_valid():
            user = serializer.validated_data['user']
            data = {'message': 'Logged in successfully', 'user': UserSerializer(user).data}
            # Include the refresh token in the response
            data['refresh_token'] = user.refresh_token
            return Response(data, status=status.HTTP_200_OK)
        else:
            return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

import os
from django.utils.deprecation import MiddlewareMixin
from django.http import StreamingHttpResponse
from rest_framework.response import Response

class StreamingMiddleware(MiddlewareMixin):
    def process_response(self, request, response):
        if response.status_code == 200 and hasattr(response, '_headers') and 'Content-Type' in response._headers:
            content_type = response._headers['Content-Type']
            if content_type == 'text/event-stream':
                # Save the streaming data to a file
                filename = 'openai_stream_output.txt'
                with open(filename, 'wb') as f:
                    for chunk in response.streaming_content:
                        f.write(chunk)

                # Send a success response back to the client
                return Response({"status": "success", "filename": filename}, headers={"Content-Type": "application/json"})

        return response

