import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class VirtualThreadScheduler {
    public static void main(String[] args) {
        // Create a ScheduledExecutorService using newScheduledThreadPool with virtual threads
        ScheduledExecutorService executor = Executors.newScheduledThreadPool(
            0, // Use as many threads as needed
            Thread.ofVirtual().factory()
        );

        // Schedule tasks with varying intervals
        executor.scheduleAtFixedRate(() -> System.out.println("Task executed"), 0, 60, TimeUnit.SECONDS);
        executor.scheduleAtFixedRate(() -> System.out.println("Task executed"), 60, 2 * 60, TimeUnit.SECONDS);

        // Shutdown the scheduler when done
        executor.shutdown();
    }
}

