import datetime

class NoThread:
    def __init__(self):
        self.start_time = None
        self.end_time = None

    def run(self):
        self.start_time = datetime.datetime.now()
        # Perform the computation
        self.end_time = datetime.datetime.now()

    def get_execution_time(self):
        return (self.end_time - self.start_time).total_seconds()

class ThreadTest(Thread):
    def __init__(self):
        super().__init__()
        self.start_time = None
        self.end_time = None

    def run(self):
        self.start_time = datetime.datetime.now()
        # Perform the computation
        self.end_time = datetime.datetime.now()

def main():
    no_thread = NoThread()
    no_thread.run()
    print(f"Time Consume: {no_thread.get_execution_time()} seconds")

    thread_test = ThreadTest()
    thread_test.run()
    print(f"Time Consume: {thread_test.get_execution_time()} seconds")

if __name__ == "__main__":
    main()

