However, I could just remove @fs from my path after importing images, and everything works normally.</p>
<pre><code>images['Oolong']=images['Oolong'].replace(&quot;/@fs&quot;,&quot;&quot;); //in OrderPage.jsx
</code></pre>
<p>But, I still want to know why this happened. Could anyone explain this?</p>

answer:
javascript
---
import fs from 'fs/promises';
import path from 'path';

// Define the path to the images folder
const imgFolderPath = path.join(__dirname, '../public/img/collections');

// Function to get all image files in the specified folder
async function getImageFiles(folderPath) {
  try {
    // Read the directory contents
    const files = await fs.readdir(folderPath);

    // Filter out non-image files
    const imageFiles = files.filter(file => {
      return /\.(png|jpg|jpeg|gif)$/i.test(file);
    });

    // Return the list of image file paths
    return imageFiles;
  } catch (error) {
    console.error('Error fetching images:', error);
    return [];
  }
}
---


