Title: Remix submit form onChange and get live update from useActionData().
Body: <p>I am trying to create a remix page where i want to get live preview when i change a <code>Select</code> tag. It is going through a Form since i want it to translate the data.</p>
<p>A solution to my problem could be to make <code>preventDefault</code>(first code example) to work or to find a way to make <code>useActionData()</code>(second code example) to work when using <code>useFetcher</code></p>
<p>With this code, the <code>preventDefault</code> does not work. I need <code>preventDefault</code> to work so that the selector doesn't reset. I could make the action function also send the name so that the DefaultValue in select is imported from action function, but this is going to become a big form and i dont want to refresh the whole page.</p>
<pre><code>export async function action({ request }: ActionArgs) {
    const form = new URLSearchParams(await request.text())
    const name = form.get('name');
    console.log('name', name);
    return json({ message: name ? `Hello ${name}!` : 'Select name' });
}

export default function Page() {
    const actionData = useActionData();
    console.log('actionData', actionData);

    return (
        &lt;&gt;
            &lt;Form method=&quot;post&quot;&gt;

                &lt;h1&gt;{actionData ? actionData.message : 'Select name.'}&lt;/h1&gt;

                &lt;select 
                    name=&quot;name&quot; 
                    onChange={e =&gt; {
                        e.preventDefault();
                        e.target.form.submit();
                    }}
                &gt;
                    &lt;option value=&quot;name 1&quot;&gt;Name 1&lt;/option&gt;
                    &lt;option value=&quot;name 2&quot;&gt;Name 2&lt;/option&gt;
                    &lt;option value=&quot;name 3&quot;&gt;Name 3&lt;/option&gt;
                &lt;/select&gt;

                &lt;button type=&quot;submit&quot; className=&quot;bg-blue-500 text-white font-bold py-2 px-4&quot;&gt;
                    Submit
                &lt;/button&gt;

                &lt;/Form&gt;
        &lt;/&gt;
    );
}
</code></pre>
<p>I have also tried following <a href="https://github.com/remix-run/remix/issues/1807" rel="noreferrer">https://github.com/remix-run/remix/issues/1807</a> using <code>useRef and useFetcher</code>, but even tho the action function runs, it gives me <code>undefined</code>  when logging actionData.</p>
<pre><code>export async function action({ request }: ActionArgs) {
    const form = new URLSearchParams(await request.text())
    const name = form.get('name');
    console.log('name', name);
    return json({ message: name ? `Hello ${name}!` : 'Select name' });
}

export default function Page() {
    const actionData = useActionData();
    console.log('actionData', actionData); // Gives undefined

    const formRef = useRef&lt;HTMLFormElement&gt;(null);
    const fetcher = useFetcher();

    return (
        &lt;&gt;
            &lt;fetcher.Form method=&quot;post&quot; ref={formRef}&gt;

                &lt;h1&gt;{actionData ? actionData.message : 'Select name.'}&lt;/h1&gt;

                &lt;select 
                    name=&quot;name&quot; 
                    onChange={() =&gt; {
                        fetcher.submit(formRef.current);
                    }}
                &gt;
                    &lt;option value=&quot;name 1&quot;&gt;Name 1&lt;/option&gt;
                    &lt;option value=&quot;name 2&quot;&gt;Name 2&lt;/option&gt;
                    &lt;option value=&quot;name 3&quot;&gt;Name 3&lt;/option&gt;
                &lt;/select&gt;

                &lt;button type=&quot;submit&quot; className=&quot;bg-blue-500 text-white font-bold py-2 px-4&quot;&gt;
                    Submit
                &lt;/button&gt;

            &lt;/fetcher.Form &gt;
        &lt;/&gt;
    );
}
</code></pre>

answer:
jsx
import { useState, useEffect } from 'react';
import { useFetcher } from '@remix-run/react';

export async function action({ request }: ActionArgs) {
    const form = new URLSearchParams(await request.text());
    const name = form.get('name');
    console.log('name', name);
    return json({ message: name ? `Hello ${name}!` : 'Select name' });
}

export default function Page() {
    const [selectedOption, setSelectedOption] = useState('');
    const actionData = useActionData();
    const formRef = useRef<HTMLFormElement>(null);
    const fetcher = useFetcher();

    useEffect(() => {
        if (actionData && actionData.message) {
            setSelectedOption(actionData.message.split(' ')[1]);
        }
    }, [actionData]);

    const handleChange = (e) => {
        setSelectedOption(e.target.value);
        fetcher.submit(formRef.current);
    };

    return (
        <div>
            <h1>{actionData ? actionData.message : 'Select name.'}</h1>

            <select 
                name="name" 
                value={selectedOption} 
                onChange={handleChange} 
                ref={formRef}
            >
                <option value="">Select name</option>
                <option value="name 1">Name 1</option>
                <option value="name 2">Name 2</option>
                <option value="name 3">Name 3</option>
            </select>

            <button type="submit" className="bg-blue-500 text-white font-bold py-2 px-4">
                Submit
            </button>
        </div>
    );
}

