# Import necessary packages
from typing import List, Tuple

def split_address(address: str) -> Tuple[str, str, str, str, str]:
    # Split the address into parts
    parts = address.split(', ')
    if len(parts) == 5:
        return parts[0], parts[1], parts[2], parts[3], parts[4]
    elif len(parts) == 4:
        return parts[0], parts[1], parts[2], None, parts[3]
    elif len(parts) == 3:
        return parts[0], parts[1], None, None, parts[2]
    elif len(parts) == 2:
        return parts[0], parts[1], None, None, None
    else:
        raise ValueError("Invalid address format")

# Example usage
address = "123 Main St, Anytown, USA"
street_number, street_name, city, state, zip_code = split_address(address)
print(f"Street Number: {street_number}, Street Name: {street_name}, City: {city}, State: {state}, Zip Code: {zip_code}")

