import subprocess

def check_exported_function_visibility():
    # Function to test transversal visibility of exported function
    def test_transversal_visibility(shell):
        try:
            result = subprocess.run([shell, "-c", "bash -c fn"], capture_output=True, text=True, check=True)
            return True, result.stdout.strip()
        except subprocess.CalledProcessError as e:
            return False, str(e)

    # List of available shells
    available_shells = [
        "/bin/bash",
        "/bin/sh",
        "/bin/zsh",
        "/bin/tcsh",
        "/bin/dash",
        "/bin/ash"
    ]

    # Check transversal visibility for each shell
    results = {}
    for shell in available_shells:
        success, output = test_transversal_visibility(shell)
        results[shell] = (success, output)

    return results

if __name__ == "__main__":
    results = check_exported_function_visibility()
    for shell, (success, output) in results.items():
        print(f"Shell: {shell}")
        if success:
            print("Transversal visibility is maintained.")
            print(output)
        else:
            print("Transversal visibility is not maintained.")
            print(output)

