    # Render the final response
    $self->render('response', content => $self->session->{content});
};

post '/example' => sub {
    my $self = shift;
    my $content = $self->param('content');

    # Store the content in the session for later rendering
    $self->session->{content} = $content;
    $self->session->{async_done} = 1;

    # Start an asynchronous task
    $self->task('process_content', {content => $content}, sub ($data) {
        my $self = shift;
        $self->session->{content} = $data->{content};
        $self->session->{async_done} = 1;
    });
};

task 'process_content' => sub ($args) {
    my ($self, $data) = @_;
    my $content = $data->{content};

    # Simulate processing time
    sleep(5);

    # Set the content in the session
    $self->session->{content} = $content;
    $self->session->{async_done} = 1;
};

