import os

def main():
    # Example usage
    url = "https://www.example.com"
    print(f"The TLD for {url} is {get_tld(url)}")

def get_tld(url):
    # Split the URL by the first slash and take the second part
    parts = url.split('/')
    if len(parts) > 1:
        return parts[1].strip('.')
    return None

if __name__ == "__main__":
    main()

import os

def get_subdomain(domain):
    # Placeholder function to simulate getting subdomain from domain name
    return domain.split('.')[0]

def get_domain(domain):
    # Placeholder function to simulate getting domain part from domain name
    return '.'.join(domain.split('.')[:-1])

def get_public_suffix(domain):
    # Placeholder function to simulate getting public suffix from domain name
    return os.path.splitext(domain)[1]

def redirect_url(url):
    subdomain = get_subdomain(url)
    domain = get_domain(url)
    public_suffix = get_public_suffix(domain)

    if subdomain == 'public':
        if public_suffix != '.pdf' and public_suffix != 'certain-url':
            print(f"Redirecting {url} to www.{domain}")
            return f"http://www.{domain}"
        else:
            print(f"URL {url} will not be redirected")
            return url
    elif subdomain == 'private':
        print(f"Redirecting {url} to www.{domain}")
        return f"https://{domain}"
    else:
        print(f"Redirecting {url} to {url}")
        return url

# Example usage
print(redirect_url('http://public.example.com'))
print(redirect_url('http://public.example.com/any-existing-file.pdf'))
print(redirect_url('http://public.example.com/any-not-existing-file.pdf'))
print(redirect_url('http://public.example.com/anything-except-certain-url-below'))
print(redirect_url('http://public.example.com/certain-url'))

# Import necessary modules
from django.core.files import move_file_safe
from rest_framework.response import Response
from rest_framework.views import APIView

class OrderUploadView(APIView):
    def post(self, request):
        file = request.FILES['file']
        base_dir = '/path/to/upload/directory'
        upload_path = os.path.join(base_dir, file.name)
        try:
            os.makedirs(os.path.dirname(upload_path), exist_ok=True)
            with open(upload_path, 'wb+') as destination:
                for chunk in file.chunks():
                    destination.write(chunk)
            return Response({'message': 'File uploaded successfully'})
        except Exception as e:
            return Response({'error': str(e)}, status=500)

