answer:
To calculate the sum and average of all values in a Python dictionary by key name, you can use the following approach:

```python
import numpy as np

# Sample data representing tree dimensions
tree_data = {
    'trees': [
        {
            'tree_idx': 0,
            'dimensions': (1120, 640),
            'branches': [
                {
                    'leaves': [
                        {'geometry': [[0.190673828125, 0.0859375], [0.74609375, 0.1181640625]]},
                        {'geometry': [[0.1171875, 0.1162109375], [0.8076171875, 0.15625]]}
                    ]
                },
                {
                    'leaves': [
                        {'geometry': [[0.2197265625, 0.1552734375], [0.7119140625, 0.1943359375]]},
                        {'geometry': [[0.2060546875, 0.1923828125], [0.730712890625, 0.23046875]]}
                    ]
                }
            ]
        }
    ]
}

# Extracting geometry information
geometries = []
for tree in tree_data['trees']:
    for branch in tree['branches']:
        for leaf in branch['leaves']:
            geometries.append((leaf['geometry'][1][1] - leaf['geometry'][0][1], leaf['geometry'][1][0] - leaf['geometry'][0][0]))

# Calculating sum and average of widths and heights
total_width = sum(geom[0] for geom in geometries)
total_height = sum(geom[1] for geom in geometries)
average_width = total_width / len(geometries)
average_height = total_height / len(geometries)

print(f"Total Width: {total_width}")
print(f"Average Width: {average_width}")
print(f"Total Height: {total_height}")
print(f"Average Height: {average_height}")
```

### Explanation:
1. **Data Extraction**: We extract the geometric coordinates of each leaf's boundary using `leaf['geometry'][1][1]` and `leaf['geometry'][0][1]`.
2. **Sum Calculation**: We compute the sum of the widths and heights separately using list comprehensions.
3. **Average Calculation**: We calculate the average of the widths and heights by dividing the sums by the number of leaves.

This method avoids nested loops and leverages list comprehensions for concise and efficient computation.

class DoubleHashingHashMap:
    def __init__(self):
        self.prime = 7
        self.size = 15
        self.slots = [EMPTY] * self.size

    def __setitem__(self, key, value):
        for idx in self.probing_squence(key):
            slot = self.slots[idx]
            if slot is EMPTY:
                self.slots[idx] = (key, value)
                break
            elif isinstance(slot, tuple):
                k, v = slot
                if k == key:
                    self.slots[idx] = (key, value)
                    break

    def probing_squence(self, key):
        h1 = self.hash_func1(key) % self.size
        h2 = self.hash_func2(key) % self.size
        i = 0
        while True:
            yield (h1 + i*h2) % self.size
            i = (i + 1) % self.size

    def hash_func1(self, item):
        return hash(item)

    def hash_func2(self, item):
        return self.prime - (self.hash_func1(item) % self.prime)

hashmap = DoubleHashingHashMap()
for i in range(8):
    hashmap[str(i)] = i
print("8 items added.")
print("Going into the infinite loop when adding 9th item(which is 8)...")
hashmap[&quot;8&quot;] = 8
print("This line can be reached.")

