        game_object = get_game_object_by_name_or_tag(scene_path, "MyObject")

        self.assertIsNotNone(game_object, "Expected to find the GameObject.")
        self.assertEqual(game_object.name, "MyObject", "The found GameObject does not match the expected name.")

if __name__ == '__main__':
    unittest.main()

