</code></pre>
<p>and here is <strong>vuetify.config.js</strong>:</p>
<pre><code>global.CSS = { supports: () =&gt; false };
</code></pre>
<p>here some versions from <strong>package.json</strong>:</p>
<pre><code>  &quot;dependencies&quot;: {
    &quot;@mdi/font&quot;: &quot;7.1.96&quot;,
    &quot;@pinia/testing&quot;: &quot;^0.0.14&quot;,
    &quot;axios&quot;: &quot;^1.2.0&quot;,
    &quot;dotenv&quot;: &quot;^16.0.3&quot;,
    &quot;happy-dom&quot;: &quot;^8.1.1&quot;,
    &quot;jsdom&quot;: &quot;^20.0.3&quot;,
    &quot;lodash&quot;: &quot;^4.17.21&quot;,
    &quot;pinia&quot;: &quot;^2.0.27&quot;,
    &quot;roboto-fontface&quot;: &quot;*&quot;,
    &quot;vue&quot;: &quot;^3.2.45&quot;,
    &quot;vuetify&quot;: &quot;3.0.6&quot;,
    &quot;webfontloader&quot;: &quot;^1.0.0&quot;
