            $subName = substr($name, $pos + 1);
            $newFuncs[$current][] = $subName;
            preg_match('~^([A-Z]+(?=[A-Z])|[A-Z0-9_]*[a-z]+)~', $subName, $matches);
            if ($matches)
             {
                $loop = true;
