    $ret.= implode('|', $strs);
    $ret.= ')';
    return $ret;
 }

$members = [...get_declared_classes(), ...get_declared_interfaces(), ...get_declared_traits()];
sort($members);

// remove namespaced names for now
foreach ($members as $key =&gt; $value)
 {
    if (strpos($value, '\\') !== false)
     {
        unset($members[$key]);
