 }
$members = processRegexArray($members);

$getRegex = getRegex($members);
do
 {
    $getRegex = preg_replace('~\(([^|()]*?)\)~', '$1', $getRegex, -1, $count);
 } 
while ($count);
var_dump($getRegex);
</code></pre>
