import { toSorted } from "core-js/proxies/array";

class MyArray<T> extends Array<T> {
    static toSorted<T>(this: T[], compareFn?: (a: T, b: T) => number): T[] {
        return super.toSorted(compareFn);
    }
}

const x = new MyArray<number>([1, 2]);
const y = MyArray.toSorted(x);

console.log(y); // Output: [1, 2]

