Title: How to trigger SwiftUI DatePicker Programmatically?.
Body: <p>As Image below shows, if you type the date &quot;Jan 11 2023&quot;, it presents the date picker. What I wanna to achieve is have a button elsewhere, when that button is clicked, present this date picker automatically.</p>
<p>Does anyone know if there is a way to achieve it?</p>
<pre><code>DatePicker(&quot;Jump to&quot;, selection: $date, in: dateRange, displayedComponents: [.date]) 
</code></pre>
<p><a href="https://i.stack.imgur.com/pGgkZ.jpg" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/pGgkZ.jpg" alt="enter image description here" /></a></p>
<p>Below is a test on @rob mayoff's answer. I still couldn't
figure out why it didn't work yet.</p>
<p>I tested on Xcode 14.2 with iPhone 14 with iOS 16.2 simulator, as well as on device. What I noticed is that although the <code>triggerDatePickerPopover()</code> is called, it never be able to reach <code>button.accessibilityActivate()</code>.</p>
<pre><code>import SwiftUI

struct ContentView: View {
  @State var date: Date = .now
  let dateRange: ClosedRange&lt;Date&gt; = Date(timeIntervalSinceNow: -864000) ... Date(timeIntervalSinceNow: 864000)

  var pickerId: String { &quot;picker&quot; }

  var body: some View {
    VStack {
      DatePicker(
        &quot;Jump to&quot;,
        selection: $date,
        in: dateRange,
        displayedComponents: [.date]
      )
      .accessibilityIdentifier(pickerId)

      Button(&quot;Clicky&quot;) {
        triggerDatePickerPopover()
          print(&quot;Clicky Triggered&quot;)
      }
    }
    .padding()
  }
}

struct ContentView_Previews: PreviewProvider {
    static var previews: some View {
        ContentView()
    }
}

extension NSObject {
  func accessibilityDescendant(passing test: (Any) -&gt; Bool) -&gt; Any? {

    if test(self) { return self }

    for child in accessibilityElements ?? [] {
      if test(child) { return child }
      if let child = child as? NSObject, let answer = child.accessibilityDescendant(passing: test) {
        return answer
      }
    }

    for subview in (self as? UIView)?.subviews ?? [] {
      if test(subview) { return subview }
      if let answer = subview.accessibilityDescendant(passing: test) {
        return answer
      }
    }

    return nil
  }
}


extension NSObject {
  func accessibilityDescendant(identifiedAs id: String) -&gt; Any? {
    return accessibilityDescendant {
      // For reasons unknown, I cannot cast a UIView to a UIAccessibilityIdentification at runtime.
      return ($0 as? UIView)?.accessibilityIdentifier == id
      || ($0 as? UIAccessibilityIdentification)?.accessibilityIdentifier == id
    }
  }

    func buttonAccessibilityDescendant() -&gt; Any? {
       return accessibilityDescendant { ($0 as? NSObject)?.accessibilityTraits == .button }
     }
}

extension ContentView {
  func triggerDatePickerPopover() {
    if
      let scene = UIApplication.shared.connectedScenes.first as? UIWindowScene,
      let window = scene.windows.first,
      let picker = window.accessibilityDescendant(identifiedAs: pickerId) as? NSObject,
      let button = picker.buttonAccessibilityDescendant() as? NSObject
    {
        print(&quot;triggerDatePickerPopover&quot;)
      button.accessibilityActivate()
    }
  }
}
</code></pre>
<p><a href="https://i.stack.imgur.com/eVDwL.gif" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/eVDwL.gif" alt="enter image description here" /></a></p>
<p>Update 2:
I followed up the debug instruction. It seems that with exact same code. My inspector are missing the accessibility identifier. Not knowing why.... feels mind buggingly now.
<a href="https://i.stack.imgur.com/gnAa8.jpg" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/gnAa8.jpg" alt="enter image description here" /></a></p>
<p>Here is a link to download the project <a href="https://www.icloud.com/iclouddrive/040jHC0jwwJg3xgAEvGZShqFg#DatePickerTest" rel="nofollow noreferrer">https://www.icloud.com/iclouddrive/040jHC0jwwJg3xgAEvGZShqFg#DatePickerTest</a></p>
<p>Update 3:
@rob mayoff's solution is brilliant! For anyone reading. If it didn't work in your case, just wait. It's probably just due to device or simulator getting ready for accessibility.</p>

answer:
swift
import SwiftUI

struct ContentView: View {
    @State var date: Date = .now
    let dateRange: ClosedRange<Date> = Date(timeIntervalSinceNow: -864000) ... Date(timeIntervalSinceNow: 864000)

    var pickerId: String { "picker" }

    var body: some View {
        VStack {
            DatePicker(
                "Jump to",
                selection: $date,
                in: dateRange,
                displayedComponents: [.date]
            )
            .accessibilityIdentifier(pickerId)

            Button("Clicky") {
                triggerDatePickerPopover()
                print("Clicky Triggered")
            }
        }
        .padding()
    }
}

struct ContentView_Previews: PreviewProvider {
    static var previews: some View {
        ContentView()
    }
}

extension NSObject {
    func accessibilityDescendant(passing test: (Any) -> Bool) -> Any? {
        if test(self) { return self }

        for child in accessibilityElements ?? [] {
            if test(child) { return child }
            if let child = child as? NSObject, let answer = child.accessibilityDescendant(passing: test) {
                return answer
            }
        }

        for subview in (self as? UIView)?.subviews ?? [] {
            if test(subview) { return subview }
            if let answer = subview.accessibilityDescendant(passing: test) {
                return answer
            }
        }

        return nil
    }
}

extension NSObject {
    func accessibilityDescendant(identifiedAs id: String) -> Any? {
        return accessibilityDescendant {
            ($0 as? UIView)?.accessibilityIdentifier == id
            || ($0 as? UIAccessibilityIdentification)?.accessibilityIdentifier == id
        }
    }

    func buttonAccessibilityDescendant() -> Any? {
       return accessibilityDescendant { ($0 as? NSObject)?.accessibilityTraits == .button }
     }
}

extension ContentView {
    func triggerDatePickerPopover() {
        if
            let scene = UIApplication.shared.connectedScenes.first as? UIWindowScene,
            let window = scene.windows.first,
            let picker = window.accessibilityDescendant(identifiedAs: pickerId) as? NSObject,
            let button = picker.buttonAccessibilityDescendant() as? NSObject
        {
            print("triggerDatePickerPopover")
            button.accessibilityActivate()
        }
    }
}

