answer:
import firebase.auth
from firebase import app
from flask import Flask, jsonify
import google.oauth2.credentials

app = Flask(__name__)

@app.route('/google-signin', methods=['GET'])
def google_signin():
    # Logic to handle Google sign-in
    credentials = google.oauth2.credentials.Credentials.from_authorized_user_file('token.json')
    firebase_admin.initialize_app(app, credentials=credentials)
    auth = firebase_auth.Auth()

    try:
        result = auth.sign_in_with_popup(new firebase.auth.GoogleAuthProvider())
        print('User signed in:', result.user)
        return jsonify({'message': 'User signed in successfully'})
    except Exception as e:
        print('Error signing in:', e)
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)

