    if not access_token or not refresh_token:
        return NextResponse.json({'message': 'No tokens provided'}, status=401)

    # Verify access token
    try:
        decoded_access_token = jwt_decode(access_token)
        if datetime.datetime.now() > datetime.datetime.fromtimestamp(decoded_access_token['exp']):
            return NextResponse.json({'message': 'Access token expired'}, status=401)
    except jwt.ExpiredSignatureError:
        return NextResponse.json({'message': 'Access token expired'}, status=401)

    # Verify refresh token
    try:
        decoded_refresh_token = jwt_decode(refresh_token)
        if datetime.datetime.now() > datetime.datetime.fromtimestamp(decoded_refresh_token['exp']):
            return NextResponse.json({'message': 'Refresh token expired'}, status=401)
    except jwt.ExpiredSignatureError:
        return NextResponse.json({'message': 'Refresh token expired'}, status=401)

    # Refresh access token if needed
    new_access_token = await refresh_access_token(decoded_access_token['sub'])
    if not new_access_token:
        return NextResponse.json({'message': 'Failed to refresh access token'}, status=500)

    # Set new access token cookie
    response = NextResponse(request)
    response.cookies.set('accessToken', new_access_token, httponly=True, secure=os.getenv('NODE_ENV') == 'production')

    # Redirect to login page
    return response

# Define request and response types
Request = Any
Response = Any

